// ── AJUSTE ESTES TRÊS VALORES ────────────────────────────────
const CHAT_ID  = -1001234567890;                 // id do grupo (negativo)
const MEMBROS  = { 111111111: 'Vini', 222222222: 'Lidia' };  // from.id -> nome
const CATEGORIAS = ['Mercado','Alimentacao','Transporte','Moradia','Saude',
  'Educacao','Lazer','Assinaturas','Vestuario','Pets','Presentes',
  'Investimento','Salario','Outros'];
// ─────────────────────────────────────────────────────────────

const upd = $input.first().json;
const msg = upd.message || upd.edited_message;
if (!msg) return [];

// 1. autorizacao: precisa ser o grupo certo e um membro conhecido
if (String(msg.chat.id) !== String(CHAT_ID)) return [];
const pessoa = MEMBROS[msg.from.id];
if (!pessoa) return [];

// 2. idempotencia: guarda os ultimos update_id na memoria do workflow
const st = $getWorkflowStaticData('global');
st.vistos = st.vistos || [];
if (st.vistos.includes(upd.update_id)) return [];
st.vistos.push(upd.update_id);
if (st.vistos.length > 300) st.vistos = st.vistos.slice(-300);

// 3. triagem: sem numero que pareca dinheiro, nao gasta LLM
const texto = (msg.text || msg.caption || '').trim();
if (!texto) return [];
if (!/\d/.test(texto)) return [];

// 4. data de hoje no fuso de Sao Paulo, formato YYYY-MM-DD
const hoje = new Date().toLocaleDateString('sv-SE', { timeZone: 'America/Sao_Paulo' });

const prompt = [
  'Voce extrai lancamentos financeiros de mensagens em portugues do Brasil.',
  'Hoje e ' + hoje + ' (fuso America/Sao_Paulo).',
  'Categorias permitidas: ' + CATEGORIAS.join(', ') + '.',
  '',
  'Regras:',
  '- eh_lancamento = false se a mensagem nao registra dinheiro gasto ou recebido.',
  '- "recebi", "caiu", "entrou", "salario" e sinonimos = tipo entrada. O resto = saida.',
  '- valor sempre positivo, em reais, usando ponto como separador decimal.',
  '- resolva datas relativas ("ontem", "sexta") contra a data de hoje. Sem data explicita, use hoje.',
  '- categoria obrigatoriamente uma da lista. Se nada encaixar, use Outros.',
  '- descricao curta, ate 40 caracteres, com o estabelecimento quando houver.',
  '- confianca de 0 a 1: quao seguro voce esta do valor e da categoria.',
  '- nunca invente valor.',
  '',
  'Mensagem: ' + texto
].join('\n');

const payload = {
  contents: [{ role: 'user', parts: [{ text: prompt }] }],
  generationConfig: {
    temperature: 0,
    responseMimeType: 'application/json',
    responseSchema: {
      type: 'object',
      properties: {
        eh_lancamento: { type: 'boolean' },
        tipo:          { type: 'string', enum: ['saida', 'entrada'] },
        valor:         { type: 'number' },
        data:          { type: 'string' },
        categoria:     { type: 'string', enum: CATEGORIAS },
        descricao:     { type: 'string' },
        confianca:     { type: 'number' }
      },
      required: ['eh_lancamento','tipo','valor','data','categoria','descricao','confianca']
    }
  }
};

return [{ json: {
  update_id: upd.update_id,
  message_id: msg.message_id,
  chat_id: msg.chat.id,
  pessoa,
  texto,
  hoje,
  categorias: CATEGORIAS,
  payload
}}];

const src  = $('Triagem e prompt').first().json;
const resp = $input.first().json;

let p;
try {
  p = JSON.parse(resp.candidates[0].content.parts[0].text);
} catch (e) {
  return [];                       // modelo devolveu algo ilegivel: ignora
}
if (!p.eh_lancamento) return [];   // nao era um lancamento: silencio

// valor
const valor = Math.round(Number(p.valor) * 100) / 100;
if (!isFinite(valor) || valor <= 0) return [];

// data: aceita so YYYY-MM-DD, senao cai para hoje
const data = /^\d{4}-\d{2}-\d{2}$/.test(p.data) ? p.data : src.hoje;

// categoria: obriga a estar na lista
const categoria = src.categorias.includes(p.categoria) ? p.categoria : 'Outros';

return [{ json: {
  update_id:  src.update_id,
  data,
  competencia: data.slice(0, 7),          // YYYY-MM, o que o dashboard agrupa
  criado_em:  new Date().toISOString(),
  tipo:       p.tipo === 'entrada' ? 'entrada' : 'saida',
  valor,
  categoria,
  descricao:  String(p.descricao || '').slice(0, 60),
  pessoa:     src.pessoa,
  mensagem:   src.texto,
  confianca:  Math.round(Number(p.confianca || 0) * 100) / 100
}}];
